import {unitPages,unitQuestions,checkUnitAnswer,validUnitPage} from './comparison-unit.mjs';
const pageContent={
 connect:`<p>En familia, o con ayuda si la necesitas, piensa en una torre que se cae. Si cambias sus piezas y también su base, ¿cómo sabrías qué influyó?</p><div class="offline-idea"><strong>Una pregunta antes de empezar</strong><p>¿Qué significa para ti comparar? Puedes contarlo, señalar dos diferencias o dibujarlas. No hay nada que enviar.</p></div><p>Para esta unidad basta distinguir «igual» y «diferente». Si esas palabras o la lectura necesitan apoyo, una persona puede mostrar dos objetos grandes y seguros y leer en voz alta.</p><p>Exploraremos qué cambiamos, qué mantenemos parecido y qué observamos. Después veremos qué permiten decir los resultados. No hace falta recordar términos científicos ni calcular deprisa.</p>`,
 example:`<p><strong>Ejemplo explicado: dos aviones de papel.</strong> Queremos estudiar si la forma cambia la distancia de vuelo. Es un ejemplo inventado, no hace falta lanzar aviones.</p><ol class="steps"><li><strong>Detectar el problema</strong><p>Un avión usa papel fino y otro grueso. Además, los lanza una persona distinta. Aunque uno llegue más lejos, también podrían influir el papel y el lanzamiento.</p></li><li><strong>Mejorar la comparación</strong><p>Cambiaríamos la forma, usando hojas iguales y una manera de lanzar lo más parecida posible, desde el mismo lugar. La forma es lo que queremos comparar; las demás condiciones intentamos mantenerlas parecidas.</p></li><li><strong>Observar y reconocer límites</strong><p>Mediríamos la distancia con el mismo criterio y repetiríamos. Los lanzamientos aún pueden variar. Un diseño mejor ayuda a investigar, pero no garantiza por sí solo una explicación definitiva.</p></li></ol><p><strong>Para conversar:</strong> ¿Qué diferencia intentamos estudiar? ¿Qué otra diferencia podría confundirnos? Puedes volver a este ejemplo en cualquier momento.</p>`,
 practice:`<p>Ahora usa la idea en un puente de papel. Puedes revisar cualquiera de las dos preguntas, pedir pistas o cambiar de parte sin responder. No hace falta construir el puente.</p>`,
 transfer:`<p>Prueba la misma idea en un contexto distinto. Si quieres, explica tu plan antes de leer las opciones. Hay menos pistas, pero puedes volver al ejemplo cuando quieras.</p><p><strong>Conecta los casos:</strong> en el puente cambiaba la forma; aquí cambia la superficie. ¿Qué intentamos mantener parecido en cada caso?</p>`,
 offscreen:`<p>Aparta la pantalla si te apetece. Solo necesitas conversar o dibujar en papel; una persona puede escribir lo que otra indique.</p><ol class="steps"><li><strong>Elige una pregunta</strong><p>Por ejemplo: «¿cómo podría cambiar la distancia de un avión de papel al cambiar su forma?».</p></li><li><strong>Diseña tres apartados</strong><p>Qué cambiaría · qué mantendría parecido · qué observaría. Añade una cosa que podría variar aunque no quisieras.</p></li><li><strong>Cuenta el límite</strong><p>¿Qué podrías decir después de una prueba? ¿Qué no podrías asegurar todavía?</p></li></ol><p>No necesitas realizar el experimento, reunir materiales ni recoger datos de personas. Si una familia decide probar otra actividad real, el adulto debe valorar por separado los materiales y las condiciones seguras.</p><p><a class="button secondary" href="./comparar-en-familia.html" target="_blank" rel="noopener">Abrir ficha para imprimir (pestaña nueva)</a></p>`,
 revisit:`<p>En otro momento que elijan en familia, recuerden la idea sin abrir la app: ¿qué conviene cambiar, mantener parecido y observar cuando comparamos?</p><div class="offline-idea"><strong>Un caso para conversar después</strong><p>Una persona compara dos torres: una alta con base estrecha y otra baja con base ancha. La alta se cae. Dice «la altura es la única causa». ¿Qué otra diferencia hay? ¿Cómo mejorarías la comparación?</p></div><details><summary>Una explicación para contrastar después</summary><p>También cambia el ancho de la base. Para estudiar la altura, intentaríamos mantener parecidos base, piezas y superficie. La caída de una sola torre no permite afirmar una causa única.</p></details><p>Si cuesta recordarlo, volver al ejemplo es una opción. No hay fecha límite, recordatorio, puntuación ni registro. También pueden terminar aquí.</p>`
};
export function renderComparisonUnit(container,state){
 if(!validUnitPage(state.unitPage))throw new Error('Página de unidad desconocida');
 const title=unitPages.find(([id])=>id===state.unitPage)[1];
 container.innerHTML=`<nav class="unit-nav" aria-label="Partes de Comparar para explicar"><p>Elige cualquier parte. No hay pasos bloqueados ni obligación de completarlos.</p><div class="unit-nav-buttons">${unitPages.map(([id,label])=>`<button type="button" class="action secondary" data-unit-page="${id}" ${state.unitPage===id?'aria-current="step"':''}>${label}</button>`).join('')}</div></nav><section class="unit-content" aria-labelledby="unit-page-title"><h5 id="unit-page-title" tabindex="-1">${title}</h5>${pageContent[state.unitPage]}${Object.entries(unitQuestions).filter(([,q])=>q.page===state.unitPage).map(([id,q])=>questionMarkup(id,q,state)).join('')}</section>`;
 container.querySelectorAll('[data-unit-page]').forEach(b=>b.addEventListener('click',()=>{state.unitPage=b.dataset.unitPage;renderComparisonUnit(container,state);container.querySelector('#unit-page-title').focus();}));
 container.querySelectorAll('[data-unit-choice]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.unitQuestion;state.unitAnswers[id]=b.dataset.unitChoice;state.unitFeedback[id]='';container.querySelectorAll(`[data-unit-question="${id}"]`).forEach(other=>other.setAttribute('aria-pressed',String(other===b)));container.querySelector(`#unit-feedback-${id}`).textContent='';}));
 container.querySelectorAll('[data-unit-check]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.unitCheck;state.unitFeedback[id]=state.unitAnswers[id]?checkUnitAnswer(id,state.unitAnswers[id]).feedback:'Elige una idea para revisarla, pide una pista o cambia de parte si lo prefieres.';container.querySelector(`#unit-feedback-${id}`).textContent=state.unitFeedback[id];}));
 container.querySelectorAll('[data-unit-hint]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.unitHint,q=unitQuestions[id];state.unitHints[id]=Math.min((state.unitHints[id]||0)+1,q.hints.length);container.querySelector(`#unit-hint-${id}`).textContent=q.hints[state.unitHints[id]-1];b.textContent=state.unitHints[id]===q.hints.length?'Releer la pista':'Otra pista';}));
}
function questionMarkup(id,q,state){const hint=state.unitHints[id]||0;return `<div class="unit-question"><p>${q.context}</p><fieldset><legend>${q.title}</legend><div class="answer-options">${q.options.map(([key,label])=>`<button type="button" class="answer-option" data-unit-question="${id}" data-unit-choice="${key}" aria-pressed="${state.unitAnswers[id]===key}">${label}</button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" data-unit-check="${id}">Revisar esta idea</button><button type="button" class="action secondary" data-unit-hint="${id}">${hint===q.hints.length?'Releer la pista':hint?'Otra pista':'Una pista'}</button></div><div class="hint-feedback" id="unit-hint-${id}" role="status" aria-live="polite" aria-atomic="true">${hint?q.hints[hint-1]:''}</div><div class="feedback" id="unit-feedback-${id}" role="status" aria-live="polite" aria-atomic="true">${state.unitFeedback[id]||''}</div></div>`;}
